<?php

use ChrisReedIO\MDStaff\MDStaffConnector;
use ChrisReedIO\MDStaff\Tests\TestCase;
use Illuminate\Support\Facades\Cache;
use Saloon\Http\Faking\MockClient;

uses(TestCase::class)
    ->beforeEach(fn () => Cache::clear())
    ->afterEach(fn () => MockClient::destroyGlobal())
    ->in(__DIR__);

function cacheFacilityAccessToken(string $accessToken = 'access-token'): void
{
    Cache::put('mdstaff:access-token:'.hash('sha256', 'example/facility-id'), $accessToken, 300);
}

function facilityConnector(): MDStaffConnector
{
    cacheFacilityAccessToken();

    return MDStaffConnector::forConfiguredFacility();
}

function pngImage(): string
{
    return base64_decode(
        'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=',
        true,
    );
}

function jpegImage(): string
{
    return base64_decode(
        '',
        true,
    );
}
